// Ajuste 3.14: los encuentros raros siguen siendo posibles, pero su frecuencia relativa se reduce sin cambiar la probabilidad base de búsqueda.
function rarityWeight(r){return ({'Común':12,'Poco común':5,'Raro':1.8,'Muy rara':0.4}[r]||5)}

function eligibleSpecies(regionId, habitat, time, season){
  const region=REGIONS.find(r=>r.id===regionId);
  return region.species.filter(id=>{
    const sp=SPECIES[id];
    return sp.habitats.includes(habitat) && sp.times.includes(time) && sp.seasons.includes(season);
  });
}

// Beta 3.15: las especialidades cambian la ponderación, nunca la presencia de especies.
function researchRarityWeight(id){
 const sp=SPECIES[id],base=rarityWeight(sp.rare);
 const levels=state.upgrades||{};
 if(!levels.mammalogy&&!levels.ornithology&&!levels.herpetology&&!levels.ichthyology)return base;
 const type=taxonomyInfo(id).className;
 const tier=type==='Mammalia'?levels.mammalogy
  :type==='Aves'?levels.ornithology
  :(type==='Reptilia'||type==='Amphibia')?levels.herpetology
  :(type==='Actinopterygii'||type==='Chondrichthyes')?levels.ichthyology:0;
 if(!tier)return base;
 const multiplier=sp.rare==='Muy rara'?(tier>=2?1.45:1.10)
  :sp.rare==='Raro'?(tier>=2?1.65:1.30)
  :sp.rare==='Poco común'?(tier>=2?1.25:1.12):1;
 return base*multiplier;
}
function weightedSpeciesPick(ids,weight=researchRarityWeight){
 // Preserve the original addition and subtraction order, including floating-point ties.
 const total=ids.reduce((sum,id)=>sum+weight(id),0);
 let roll=Math.random()*total;
 for(const id of ids){roll-=weight(id);if(roll<=0)return id;}
 return ids[ids.length-1];
}
function researchEncounterTargets(source){
 const tier=Math.min(3,Math.max(0,state.upgrades.groupTier||0));
 if(!tier)return 1;
 if(source==='auto'&&!state.upgrades.autoGroup)return 1;
 const roll=Math.random();
 if(source==='auto'){
  if(tier===3&&roll<RESEARCH_V315_BALANCE.autoTriple)return 3;
  return roll<(tier===3?RESEARCH_V315_BALANCE.autoDouble+RESEARCH_V315_BALANCE.autoTriple:RESEARCH_V315_BALANCE.autoDouble)?2:1;
 }
 if(tier===3&&roll<RESEARCH_V315_BALANCE.manualTriple[tier])return 3;
 return roll<RESEARCH_V315_BALANCE.manualDouble[tier]+RESEARCH_V315_BALANCE.manualTriple[tier]?2:1;
}
function researchCensusCount(source){
 const tier=Math.max(0,state.upgrades.censusTier||0);
 if(!tier)return 1;
 if(source==='auto')return state.upgrades.autoCensus?RESEARCH_V315_BALANCE.autoCensusMultiplier:1;
 return tier>=2?3:2;
}
// Beta 3.15.1: el equipo automático recorre todos los hábitats y horarios válidos
// de la región actual, sin cambiar los filtros elegidos por quien observa manualmente.
// Estación, distribución biogeográfica y cupo por especie/hora siguen vigentes.
function automaticEligibleSpecies(regionId,season){
 const region=REGIONS.find(r=>r.id===regionId);
 if(!region)return [];
 return [...new Set(region.species)].filter(id=>{
  const sp=SPECIES[id];
  return !!sp && sp.seasons.includes(season) && sp.times.length>0
    && sp.habitats.some(h=>region.habitats.includes(h));
 });
}
function automaticSearchCapacity(at=Date.now(),ids=automaticEligibleSpecies(state.currentRegion,state.season)){
 const hour=Math.floor(at/3600000);
 const remaining=ids.filter(id=>(state.autoHourly[hour+':'+id]||0)<MAX_AUTOMATIC_SIGHTINGS_PER_SPECIES_PER_HOUR);
 return {total:ids.length,remaining:remaining.length};
}
function pruneAutomaticHours(at){
 // Preserve the historical buckets needed by work still queued, even on manual searches.
 const hour=Math.floor(Math.min(at,state.autoPending[0]?.at??at)/3600000);
 for(const key of Object.keys(state.autoHourly))if(Number(key.split(':')[0])<hour-8)delete state.autoHourly[key];
}
function encounter(source='manual', at=Date.now(), guaranteed=false, automatic=null){
 // Cada búsqueda permite una sola probabilidad de encuentro, independientemente de cuántas especies registre.
 const hour=Math.floor(at/3600000);
 const bucket=state.autoHourly;
 if(!automatic)pruneAutomaticHours(at);
 const baseChoices=source==='auto'
  ?automatic?.species??automaticEligibleSpecies(state.currentRegion,state.season)
  :eligibleSpecies(state.currentRegion,state.habitat,state.time,state.season);
 const choices=automatic?.choices??baseChoices.filter(id=>source!=='auto'
  ||(bucket[hour+':'+id]||0)<MAX_AUTOMATIC_SIGHTINGS_PER_SPECIES_PER_HOUR);
 const manual=source==='manual';
 let chanceBase=manual?0.50:0.38;
 chanceBase*=manual?manualEncounterBonus():helperBonus();
 chanceBase=Math.min(0.96,chanceBase);
 if(!choices.length&&!manual){
  const reason=baseChoices.length?'Cupo horario de observación automática agotado para las especies disponibles.':'No hay fauna compatible con esta estación en la región.';
  currentAutoNotice=reason+' El equipo reanudará avistamientos cuando corresponda; la búsqueda manual continúa disponible.';
  return;
 }
 currentAutoNotice='';
 const relicConditions=automatic?.segment??state;
 if(!choices.length||(!guaranteed&&Math.random()>chanceBase)){
  searchRelictInField(source,at,relicConditions);
  const k=Math.round((manual?3:1.5)*knowledgeBonus());
  state.knowledge+=k;
  // MEC-04: también una búsqueda sin avistamiento permite un hallazgo ambiental (una tirada).
  const ambientNoSighting=mec03AmbientFinds(ambientContextMEC04(source,automatic));
  if(manual)state.lastEncounter={title:'Sin avistamiento',subtitle:`Se encontraron rastros. +${k} conocimiento`+(ambientNoSighting.length?' · hallazgo: '+ambientNoSighting.map(i=>ITEMS[i].name).join(', '):''),sprite:null};
  if(manual)pushLog(`Búsqueda sin avistamiento · +${k} conocimiento${ambientNoSighting.length?' · hallazgo: '+ambientNoSighting.map(i=>ITEMS[i].name).join(', '):''}.`);
  if(!batchingOffline){renderCounters();updateFieldOutput();}
  return;
 }
 // Selección sin reemplazo: un encuentro múltiple siempre contiene especies diferentes.
 const pool=[...choices],selected=[];
 const maxSpecies=Math.min(pool.length,researchEncounterTargets(source));
 for(let i=0;i<maxSpecies;i++){
  const chosen=weightedSpeciesPick(pool,automatic?.weight);
  selected.push(chosen);
  pool.splice(pool.indexOf(chosen),1);
 }
 // El conocimiento y los botines del Museo se generan UNA vez por búsqueda,
 // nunca una vez por individuo del censo (evita multiplicar objetos o variantes).
 const knowledgeGain=Math.round((manual?5:3)*knowledgeBonus());
 state.knowledge+=knowledgeGain;
 const museumFinds=maybeMuseumFieldDiscovery(source,relicConditions);
 const entries=[];
 const census=researchCensusCount(source);
 for(const chosen of selected){
  const sp=SPECIES[chosen],first=!state.discovered[chosen];
  let amount=census;
  if(source==='auto'){
   const key=hour+':'+chosen;
   amount=Math.min(amount,MAX_AUTOMATIC_SIGHTINGS_PER_SPECIES_PER_HOUR-(bucket[key]||0));
   if(amount<1)continue;
   bucket[key]=(bucket[key]||0)+amount;
   if(automatic){
    automatic.hits+=amount;
    if(bucket[key]===MAX_AUTOMATIC_SIGHTINGS_PER_SPECIES_PER_HOUR)automatic.choices.splice(automatic.choices.indexOf(chosen),1);
   }
  }
  state.discovered[chosen]=true;
  state.sightings[chosen]=sight(chosen)+amount;
  regionalRecordMEC06(relicConditions.currentRegion??state.currentRegion,chosen,at);
  if(first){earnMoney(15,'descubrimientos');pushLog(`Descubrimiento de ${visibleName(chosen)}: la Sociedad entrega £15.`);}
  const note=[];
  if(Math.random()<0.12){state.feedObs[chosen]=feed(chosen)+1;note.push('comiendo');}
  // MEC-07: récords naturales y conductas (una evaluación por hito elegible y especie observada).
  note.push(...naturalRecordsMEC07(chosen,{source,at,manual,automatic,relic:relicConditions}));
  const sexObservation=recordSexObservation(chosen,manual);
  if(sexObservation){
   const sexLabel=sexObservation.sex==='male'?'macho':'hembra';
   if(sexObservation.isNew)note.push(`primera observación de ${sexLabel}`);
   if(sexObservation.complete&&sexObservation.isNew)note.push('dimorfismo documentado (2/2)');
  }
  note.push(...naturalRecordsSexMEC08(chosen,sexObservation));
  const specimen=rollSpecimen(chosen,state);
  const variant=specimen.pigment||specimen.category,category=specimen.category;
  recordSpecimen(chosen,specimen,state);
  if(variant)note.push(`espécimen especial: ${[specimen.pigment,category].filter(Boolean).join(' · ')}`);
  if(category==='Legendario')note.push(legendaryForSpecies(chosen).name);
  // Una sola oportunidad de obtener muestra por búsqueda, aunque se observen 3 especies.
  if(entries.length===0){
   const drop=maybeSpeciesDrop(chosen,manual);
   if(drop)note.push(`muestra obtenida: ${ITEMS[drop].name}`);
   // MEC-01: canales nuevos (materiales, coleccionables, rarezas), independientes del histórico.
   for(const extra of mec01FieldDrops(chosen,manual))note.push(`muestra obtenida: ${ITEMS[extra].name}`);
   // MEC-03: hallazgo ambiental según región y bioma, independiente de la especie observada.
   for(const extra of mec03AmbientFinds(ambientContextMEC04(source,automatic)))note.push(`hallazgo: ${ITEMS[extra].name}`);
   if(museumFinds.length)note.push(...museumFinds);
  }
  entries.push({id:chosen,first,amount,note,variant,category,sexObservation});
 }
 if(!entries.length)return;
 const relict=searchRelictInField(source,at,relicConditions);
 const clue=maybeMuseumRelictLead(source,Math.random,relicConditions);
 if(relict)entries[0].note.push('relicto: '+relict.name);
 if(clue)entries[0].note.push('indicio: '+clue);
 const sequence=state.encounterSequence=(state.encounterSequence||0)+1;
 if(automatic?.deferPresentation)automatic.latest={entries,knowledgeGain,sequence};
 else presentEncounter(entries,knowledgeGain,sequence);
 if(manual)pushLog(`${entries.length>1?'Encuentro múltiple · ':''}${entries.map(e=>visibleName(e.id)+' ×'+e.amount).join(', ')}${entries[0].note.length?' · '+entries[0].note.join(', '):''}.`);
 if(!batchingOffline){renderCounters();updateFieldOutput();}
}
function presentEncounter(entries,knowledgeGain,sequence){
 const primary=entries[0],sp=SPECIES[primary.id],many=entries.length>1;
 const title=many?`Encuentro múltiple: ${entries.length} especies`
  :`${primary.first?'¡Nueva especie! ':'Avistamiento: '}${visibleName(primary.id)}`;
 const summary=many?entries.map(e=>`${visibleName(e.id)} ×${e.amount}`).join(' · '):`${fmt(sight(primary.id))} avistamientos`;
 const subtitle=`${many?summary:sp.rare+(primary.variant?` · ${primary.variant}`:'')+' · '+summary} · +${knowledgeGain} conocimiento${primary.first?' · +£15':''}${primary.note.length?' · '+primary.note.join(', '):''}`;
 state.lastEncounter={species:primary.id,title,subtitle,sprite:primary.variant?specimenMarkup(primary.id,primary.variant,primary.category)
   :(primary.sexObservation?getSpriteMarkup(primary.id,'normal',primary.sexObservation.sex):getSpriteMarkup(primary.id)),
   sequence,entries:entries.map(e=>({id:e.id,amount:e.amount,variant:e.variant||'',category:e.category||'',sex:e.sexObservation?.sex||null,first:e.first}))};
}
function variantToSkin(variant){
  if(/albino|leuc/i.test(variant)) return 'albino';
  if(/mel[aá]n/i.test(variant)) return 'melanico';
  if(/notable/i.test(variant)) return 'alfa';
  if(/épico/i.test(variant)) return 'epico';
  if(/excepcional/i.test(variant)) return 'excepcional';
  if(/legendario/i.test(variant)) return 'legendario';
  return 'normal';
}

function pushLog(txt){
 const last=state.log[0];
 if(last && last===txt){state.logRepeated=(state.logRepeated||0)+1; return;}
 state.logRepeated=0; state.log.unshift(txt); state.log=state.log.slice(0,8);diaryDirty=true;
}

function stageRequirements(id, nextIndex){
  const sp=SPECIES[id];
  const needSight=THRESHOLDS[nextIndex];
  const money=SPECIES_MONEY_COSTS[nextIndex];
  const knowledge=SPECIES_KNOWLEDGE_COSTS[nextIndex];
  const req={needSight,money,knowledge,label:STAGE_LABELS[nextIndex], extra:'Ninguno'};
  if(nextIndex===3){ // stage 4 / index 3
    req.extra = sp.dimorphism ? `Requiere 10 observaciones comiendo o registrar macho y hembra.` : `Requiere 10 observaciones comiendo.`;
    req.extraOk = feed(id)>=10 || (sp.dimorphism && hasDimorphism(id));
  } else if(nextIndex===4){
    req.extra = `Requiere al menos 1 espécimen especial.`;
    req.extraOk = specials(id)>=1;
  } else req.extraOk=true;
  req.sightOk = sight(id)>=needSight;
  req.moneyOk = state.money>=money;
  req.knowledgeOk = state.knowledge>=knowledge;
  req.allOk = req.sightOk && req.moneyOk && req.knowledgeOk && req.extraOk;
  return req;
}
function advanceSpecies(id){
  const current=stage(id);
  if(current>=5) return;
  const req=stageRequirements(id,current);
  if(!req.allOk) return;
  state.money-=req.money;
  state.knowledge-=req.knowledge;
  state.stages[id]=current+1;
  pushLog(`${SPECIES[id].name} avanzó a ${state.stages[id]}/5.`);
  render();
}
function publishMonograph(id){
  if(stage(id)<5 || state.published[id]) return;
  state.published[id]=true;
  state.prestige+=1;
  earnMoney(90,'publicaciones');
if(state.prestige>=2) state.regionUnlocked[REGIONS[2].id]=true;
  pushLog(`Monografía publicada: ${SPECIES[id].name}. +1 prestigio, +£90.`);
  render();
}

function requestGrant(){
  const now=Date.now();
  if(now-state.lastGrant < 60000) return;
  const discovered=Object.keys(state.discovered).length;
  if(discovered===0) return;
  const grant=Math.round((35+discovered*5)*(1+(state.upgrades.grantBonus||0)+(state.equipment.necklace==='amber_charm'?0.05:0)));
  earnMoney(grant,'subvenciones');
  state.lastGrant=now;
  pushLog(`La Sociedad concede una subvención de £${grant}.`);
  render();
}
function exchangeNotes(){
  if(state.knowledge<40) return;
  state.knowledge-=40;
  const reward=Math.round(25*(1+(state.upgrades.noteBonus||0)));
  earnMoney(reward,'canjeNotas');
  pushLog(`Notas de campo canjeadas: -40 conocimiento, +£${reward}.`);
  render();
}
function craftTome(){
  if(state.knowledge<10000) return;
  state.knowledge-=10000;
  state.books+=1;
  pushLog('Has compilado un Tomo de historia natural.');
  render();
}
function unlockRegion(id){
  const region=REGIONS.find(r=>r.id===id);
  if(state.regionUnlocked[id]) return;
  if(state.prestige >= region.unlock.prestige){ state.regionUnlocked[id]=true; render(); }
}
function regionAccessible(r){
  if(!r) return false;
  return !!state.regionUnlocked[r.id] || r.id===state.currentRegion;
}

function setRegion(id){
  const dest=REGIONS.find(r=>r.id===id);
  if(!dest || !(state.regionUnlocked[id] || id===state.currentRegion)) return;
  state.currentRegion=id;
  state.regionsVisited=state.regionsVisited||{};
  state.regionsVisited[id]=true;
  if(!dest.habitats.includes(state.habitat))state.habitat=dest.habitats[0];
  if(!eligibleSpecies(id,state.habitat,state.time,state.season).length){
    const prefs=['amanecer','dia','atardecer','noche'];
    let found=false;
    for(const habitat of dest.habitats){
      for(const time of [state.time,...prefs]){
        if(eligibleSpecies(id,habitat,time,state.season).length){state.habitat=habitat;state.time=time;found=true;break;}
      }
      if(found)break;
    }
  }
  state.lastEncounter=null;
  currentAutoNotice='';
  pushLog(`Expedición terrestre: llegada a ${dest.name}.`);
  render();
}

function canBuy(node){
  if(node.once && state.purchases[node.id]) return false;
  if(node.max && (state.purchases[node.id]||0)>=node.max) return false;
  if(node.req && !state.purchases[node.req]) return false;
  if(node.reqAll && !node.reqAll.every(id=>state.purchases[id]))return false;
  if(node.reqItem && (state.inventory[node.reqItem]||0)<(node.reqItemQty||1)) return false;
  return state.money>=node.money && state.knowledge>=node.knowledge;
}
function buyNode(id){
  const node=RESEARCH_NODES.find(n=>n.id===id); if(!node) return;
 // E-3280 BEGIN purchase-validation
  if(!canBuy(node))return;
 // E-3280 END purchase-validation
  if(node.once && state.purchases[id]) return;
  if(node.max && (state.purchases[id]||0)>=node.max) return;
  if(node.req && !state.purchases[node.req]) return;
  if(node.reqItem && (state.inventory[node.reqItem]||0)<(node.reqItemQty||1)) return;
  if(state.money<node.money || state.knowledge<node.knowledge) return;
  state.money-=node.money; state.knowledge-=node.knowledge;
  if(node.reqItem && node.reqItemConsume!==false) state.inventory[node.reqItem]=(state.inventory[node.reqItem]||0)-(node.reqItemQty||1);
  state.purchases[id]=(state.purchases[id]||0)+1;
  node.effect(state);
  if(id==='relictos_1'||id==='relictos_2'){
   const needsClue=r=>state.regionUnlocked[r.region]&&!museumRelictOwned(r.id)&&relictLeadCount(r.id)<3;
   const relict=relictsByRegion.get(state.currentRegion)?.find(needsClue)??MUSEUM_RELICTS.find(needsClue);
   if(relict)addRelictLead(relict.id);
  }
  pushLog(`Investigación completada: ${node.name}.`);
  render();
}

function setCounterText(id,text){
 const node=$(id);
 if(node.textContent!==text)node.textContent=text;
}
