function regionRequirementsMet(r){
  if(!r) return false;
  if(r.continent==='Asia') return !!(state.upgrades.asiaUnlocked && state.prestige>=r.unlock.prestige);
  if(r.continent==='África') return !!(state.inventory?.africa_map && (state.upgrades.africaUnlocked || state.regionUnlocked[r.id]) && state.prestige>=r.unlock.prestige);
   if(r.continent==='Norteamérica')return !!(state.upgrades.northAmericaUnlocked && state.inventory?.north_america_map && state.prestige>=r.unlock.prestige);
  return state.prestige>=r.unlock.prestige;
}
function continentStatus(continent){
  if(continent==='Europa') return 'available';
  if(continent==='Asia') return state.upgrades.asiaUnlocked?'available':'unlockable';
  if(continent==='África') return state.inventory?.africa_map&&state.upgrades.africaUnlocked?'available':'unlockable';
  if(continent==='Norteamérica')return state.upgrades.northAmericaUnlocked?'available':'unlockable';
  return 'locked';
}
function unlockRegion(id){
  const r=REGIONS.find(x=>x.id===id); if(!r || !regionRequirementsMet(r)) return;
  state.regionUnlocked[id]=true; pushLog('Región desbloqueada: '+r.name+'.'); render();
}
function travelToRegion(id){ setRegion(id); tab='field'; renderPanel(); persist(); }
function spendMoneyForKnowledge(multiplier=1){
  if(![1,10,100,1000].includes(multiplier)) return;
  const max=state.purchases.fondos_x1000?1000:state.purchases.fondos_x100?100:state.purchases.fondos_x10?10:1;
  if(multiplier>max) return;
  const cost=100*multiplier, gain=70*multiplier;
  if(state.money<cost) return;
  state.money-=cost; state.knowledge+=gain;
  pushLog('Aporte científico ×'+multiplier+': £'+fmt(cost)+' por '+fmt(gain)+' conocimiento.');
  render();
}
function compileAtlas(){
  const total=Object.keys(state.published).length;
  if(total<20 || state.knowledge<500) return;
  state.knowledge-=500; state.prestige+=1; pushLog('Atlas general compilado: +1 prestigio.'); render();
}
function removeExhibit(id){
  if(!state.museum.exhibits[id]) return;
  delete state.museum.exhibits[id]; pushLog('Se retiró de la sala: '+SPECIES[id].name); render();
}
function bestiaryTypeBucket(id){
  const c=taxonomyInfo(id).className;
  if(c==='Mammalia') return 'Mamífero';
  if(c==='Aves') return 'Ave';
  if(c==='Actinopterygii'||c==='Chondrichthyes') return 'Pez';
  return 'Reptil/Anfibio';
}
