 for(const p of [...MUSEUM_COLLECTIONS,...MUSEUM_FOSSIL_RECIPES,...MUSEUM_CURATORIAL_PROJECTS])if(p.requires[id])uses.push({name:p.name,action:'museum',id:p.tab==='artifacts'?'artifacts':'fossils',kind:'museum'});
